/* Studio and guest controls. Prices shown here mirror the server's per-photo fallback. */
let galleryQuery='',galleryStatus='all',gallerySort='newest',photoQuery='',photoSort='newest',photoFilter='all',guestQuery='',guestFilter='all',guestSort='newest';
let galleryPageData=null,galleryPageOffset=0,sharePageOffset=0,galleryRequest=0,galleryDebounce=null;
function galleryPageURL(filtered,offset=0){const q=new URLSearchParams({limit:'30',offset:String(offset)});if(filtered){if(galleryQuery)q.set('q',galleryQuery);if(galleryStatus!=='all')q.set('status',galleryStatus);q.set('sort',gallerySort)}return '/api/galleries?'+q}
function galleryPagination(mode){let offset=mode==='share'?sharePageOffset:galleryPageOffset,total=galleryPageData?.total||0,fn=mode==='share'?'changeSharePage':'changeGalleryPage';return `<div class="order-pagination"><span>Showing ${galleries.length?offset+1:0}–${offset+galleries.length} of ${total}</span><div class="details-bar"><button class="btn" onclick="${fn}(-30)" ${offset===0?'disabled':''}>← Previous</button><button class="btn" onclick="${fn}(30)" ${!galleryPageData?.has_more?'disabled':''}>Next →</button></div></div>`}
async function fetchGalleryPage(gen){try{let result=await api(galleryPageURL(true,galleryPageOffset));if(gen!==galleryRequest||view!=='galleries')return;galleryPageData=result;galleries=result.items;document.querySelector('#gallery-list').innerHTML=galleryCards();document.querySelector('#gallery-pagination').innerHTML=galleryPagination('galleries');icons()}catch(e){if(gen===galleryRequest)toast(e.message)}}
function changeGalleryPage(delta){galleryPageOffset=Math.max(0,galleryPageOffset+delta);fetchGalleryPage(++galleryRequest)}
async function changeSharePage(delta){sharePageOffset=Math.max(0,sharePageOffset+delta);const gen=++galleryRequest;try{let result=await api(galleryPageURL(false,sharePageOffset));if(gen!==galleryRequest||view!=='share')return;galleryPageData=result;galleries=result.items;render()}catch(e){if(gen===galleryRequest)toast(e.message)}}
let ownerPhotoLimit=60,ownerPhotoSignature='',guestPhotoLimit=60,guestPhotoSignature='';
let theme=localStorage.getItem('lumen-theme')||'light';
function applyTheme(){document.documentElement.dataset.theme=theme;localStorage.setItem('lumen-theme',theme)}
function toggleTheme(){theme=theme==='dark'?'light':'dark';applyTheme();document.querySelectorAll('.theme-toggle').forEach(b=>b.innerHTML=theme==='dark'?'☀ Light':'☾ Dark')}
applyTheme();
const originalShell=shell;
shell=function(content){let html=originalShell(content).replaceAll('Pictide Studio',esc(studioSettings.studio_name));html=html.replace('</nav>','<button class="btn theme-toggle side-theme" onclick="toggleTheme()">'+(theme==="dark"?"☀ Light":"☾ Dark")+'</button></nav>');return html.replace('<div class="top-right">','<div class="top-right"><button class="btn theme-toggle" onclick="toggleTheme()">'+(theme==='dark'?'☀ Light':'☾ Dark')+'</button>')}
function photoPrice(p){return p.price??current.price}
function selectionTotal(){return current.photos.filter(p=>selected.has(p.id)).reduce((n,p)=>n+photoPrice(p),0)}
function options(items,value){return items.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}
function sortPhotos(photos,sort){let a=[...photos];a.sort((x,y)=>sort==='oldest'?x.created.localeCompare(y.created):sort==='name'?x.name.localeCompare(y.name):sort==='price-low'?photoPrice(x)-photoPrice(y):sort==='price-high'?photoPrice(y)-photoPrice(x):y.created.localeCompare(x.created));return a}
galleryList=function(){return `<div class="page-head"><div><div class="eyebrow">Your body of work</div><h1>Galleries</h1><p class="sub">Every story has a place here.</p></div><button class="btn primary" onclick="galleryModal()">${icon('plus')} New gallery</button></div><div class="toolbar filters"><input class="search" aria-label="Search galleries" placeholder="Search galleries..." value="${esc(galleryQuery)}" oninput="galleryQuery=this.value;updateGalleryList()"><select aria-label="Gallery status" onchange="galleryStatus=this.value;updateGalleryList()">${options([['all','All statuses'],['Published','Published'],['Draft','Draft']],galleryStatus)}</select><select aria-label="Sort galleries" onchange="gallerySort=this.value;updateGalleryList()">${options([['newest','Newest first'],['oldest','Oldest first'],['name','Name A–Z'],['photos','Most photos']],gallerySort)}</select></div><div class="gallery-grid" id="gallery-list">${galleryCards()}</div><div id="gallery-pagination">${galleryPagination('galleries')}</div>`}
function galleryCards(){return galleries.map(card).join('')||'<div class="empty-state">No galleries match these filters.</div>'}
function updateGalleryList(){galleryPageOffset=0;let gen=++galleryRequest;clearTimeout(galleryDebounce);galleryDebounce=setTimeout(()=>fetchGalleryPage(gen),200)}
detail=function(){let g=current;return `<button class="text-link" onclick="navigate('galleries')">← &nbsp; All galleries</button><div class="page-head"><div><div class="eyebrow">${esc(g.status)} gallery</div><h1>${esc(g.name)}</h1><p class="sub">${esc(g.client||'Personal gallery')} · ${date(g.event_date)} · Default ${money(g.price)} per photo</p></div><div class="details-bar"><button class="btn" onclick="galleryModal(current)">${icon('pencil')} Edit details</button><button class="btn" onclick="brandingModal()">${icon('palette')} Branding</button><button class="btn" onclick="window.open('/?gallery=${g.id}&preview=1','_blank')">${icon('eye')} Guest preview</button><button class="btn" onclick="shareModal('${g.id}')">${icon('share-2')} Share</button><button class="btn primary" onclick="document.querySelector('#upload').click()">${icon('upload')} Add photos</button><input id="upload" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden onchange="uploadPhotos(this)"></div></div><div class="table-wrap notice"><span><b>${g.status==='Published'?'Gallery is live':'Your gallery is a draft'}</b><br><small class="sub">${g.status==='Published'?'Guests with the link can view this gallery.':'Publish when you are ready to share.'}</small></span><button class="btn" onclick="togglePublish()">${g.status==='Published'?'Unpublish':'Publish gallery'}</button></div><div class="table-wrap notice"><span><b>Guest contributions ${g.allow_guest_upload?'enabled':'disabled'}</b><br><small class="sub">Submissions are private until you approve them.</small><span id="contribution-preview" class="contribution-preview">Loading submissions…</span></span><div class="details-bar"><button class="btn" onclick="reviewUploads()">Review uploads</button><button class="btn" onclick="toggleGuestUploads()">${g.allow_guest_upload?'Disable uploads':'Allow guest uploads'}</button></div></div><div class="section-title"><div><h2>Photographs</h2><p class="sub">${g.photos.length} photos · Select a price tag to customize it</p></div><button class="text-link" onclick="deleteGallery()" style="color:#a47769">Delete gallery</button></div><div class="toolbar filters"><input class="search" aria-label="Search photos" placeholder="Search by filename..." value="${esc(photoQuery)}" oninput="photoQuery=this.value;updateOwnerPhotos()"><select aria-label="Filter photo prices" onchange="photoFilter=this.value;updateOwnerPhotos()">${options([['all','All prices'],['custom','Custom prices'],['default','Gallery default']],photoFilter)}</select><select aria-label="Sort photos" onchange="photoSort=this.value;updateOwnerPhotos()">${options([['newest','Newest first'],['oldest','Oldest first'],['name','Name A–Z'],['price-low','Price: low to high'],['price-high','Price: high to low']],photoSort)}</select></div><div class="detail-grid" id="owner-photos">${ownerPhotoCards()}</div><div id="owner-photo-more">${ownerPhotoMore()}</div>`}
function ownerPhotoCards(){let list=sortPhotos(current.photos.filter(p=>p.name.toLowerCase().includes(photoQuery.toLowerCase())&&(photoFilter==='all'||photoFilter==='custom'&&p.price!==null||photoFilter==='default'&&p.price===null)),photoSort);return list.slice(0,ownerPhotoLimit).map(p=>`<div class="photo"><img loading="lazy" decoding="async" src="/media/${p.id}?size=thumb&v=${Date.now()}" alt="${esc(p.name)}"><button title="Remove photo" aria-label="Remove ${esc(p.name)}" onclick="deletePhoto('${p.id}')">×</button><button class="cover-control" title="${current.cover_photo===p.id?'Remove cover photo':'Set as cover photo'}" aria-label="${current.cover_photo===p.id?'Remove cover photo':'Set as cover photo'}" onclick="setGalleryCover('${p.id}')">${current.cover_photo===p.id?'★':'☆'}</button><button class="price-tag" onclick="priceModal('${p.id}')">${photoPrice(p)===0?'Free':money(photoPrice(p))} ✎</button><span class="photo-name">${esc(p.name)}</span></div>`).join('')||'<div class="empty-state">No photos match. Upload photographs or change your search.</div>'}
async function setGalleryCover(id){try{await api('/api/galleries/'+current.id+'/cover',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({photo:current.cover_photo===id?'':id})});await refresh();await openGallery(current.id);toast(current.cover_photo?'Cover photo updated':'Cover photo removed')}catch(e){toast(e.message)}}
function filteredOwnerPhotos(){return current.photos.filter(p=>p.name.toLowerCase().includes(photoQuery.toLowerCase())&&(photoFilter==='all'||photoFilter==='custom'&&p.price!==null||photoFilter==='default'&&p.price===null))}
function ownerPhotoMore(){let total=filteredOwnerPhotos().length;return total>ownerPhotoLimit?`<div class="photo-load-more"><span>Showing ${Math.min(ownerPhotoLimit,total)} of ${total} photographs</span><button class="btn" onclick="loadMoreOwnerPhotos()">Load more</button></div>`:''}
function updateOwnerPhotos(){let sig=JSON.stringify([current.id,photoQuery,photoFilter,photoSort]);if(sig!==ownerPhotoSignature){ownerPhotoSignature=sig;ownerPhotoLimit=60}document.querySelector('#owner-photos').innerHTML=ownerPhotoCards();let more=document.querySelector('#owner-photo-more');if(more)more.innerHTML=ownerPhotoMore()}
function loadMoreOwnerPhotos(){ownerPhotoLimit+=60;updateOwnerPhotos()}
function priceModal(id){let p=current.photos.find(x=>x.id===id);modal(`<div class="modal-head"><div><div class="eyebrow">Individual pricing</div><h2>Set photo price</h2><p class="sub">${esc(p.name)}</p></div><button class="close" onclick="closeModal()">×</button></div><form onsubmit="savePhotoPrice(event,'${id}')"><label class="field">Price in naira<input name="price" type="number" min="0" step="0.01" placeholder="Default: ${current.price/100}" value="${p.price===null?'':p.price/100}"></label><p class="sub">Enter 0 to make this photo free, or leave blank to use the gallery default of ${money(current.price)}.</p><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save price</button></div></form>`)}
async function savePhotoPrice(e,id){e.preventDefault();let v=new FormData(e.target).get('price');try{await api('/api/photos/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({price:v===''?null:Number(v)})});closeModal();await openGallery(current.id);toast('Photo price updated')}catch(err){toast(err.message)}}
settingsView=function(){return `<div class="page-head"><div><div class="eyebrow">Your workspace</div><h1>Settings</h1><p class="sub">Make this studio feel like yours.</p></div></div><div class="settings-grid"><form class="settings-card" onsubmit="saveSettings(event)"><h2>Studio profile</h2><p class="sub">These defaults apply across your workspace and new galleries.</p><label class="field">Studio name<input name="studio_name" maxlength="80" required value="${esc(studioSettings.studio_name)}"></label><label class="field">Default price per photo (₦)<input name="default_price" type="number" min="0" step="0.01" value="${studioSettings.default_price}" required></label><label class="field">Public contact email<input name="contact_email" type="email" maxlength="254" value="${esc(studioSettings.contact_email||'')}" placeholder="Optional: guests can contact you"></label><button class="btn primary" style="margin-top:20px">Save settings</button></form><div class="settings-card"><h2>Appearance</h2><p class="sub">Choose the look of this browser. Guests can choose their own theme.</p><button class="btn theme-toggle" style="margin-top:18px" onclick="toggleTheme()">${theme==='dark'?'☀ Light':'☾ Dark'}</button><h2 style="margin-top:32px">Studio brand mark</h2><p class="sub">This mark appears on every gallery unless that gallery has its own mark. Choose a transparent PNG for the cleanest result.</p><label class="field">${studioSettings.studio_logo?'Replace brand mark':'Upload brand mark'}<input id="studio-logo" type="file" accept="image/png,image/jpeg,image/webp" onchange="uploadStudioLogo(this)"></label>${studioSettings.studio_logo?'<button class="text-link" onclick="removeStudioLogo()">Remove studio brand mark</button>':''}<button class="btn" style="margin-top:12px" onclick="applyStudioBrand()">Apply brand to existing photos</button><h2 style="margin-top:32px">Account email</h2><p class="sub">Verify an email address to enable password recovery.</p><button class="btn" style="margin-top:12px" onclick="accountEmailModal()">Set recovery email</button><h2 style="margin-top:32px">Security</h2><p class="sub">Protect the studio with a password. Changing it signs out existing sessions.</p><button class="btn" style="margin-top:12px" onclick="passwordModal()">${sessionInfo.passwordRequired?'Change password':'Set password'}</button><h2 style="margin-top:32px">Preview storage</h2><p class="sub">${config.imgbb_previews?'ImgBB is enabled for published previews. Originals and private images remain local.':'Published previews are stored locally.'}</p><h2 style="margin-top:32px">Payments</h2><p class="sub">Payment mode: <b>${esc(config.payments)}</b>. Credentials and the studio password are configured on the server. See the README for setup and backups.</p>${sessionInfo.passwordRequired?'<button class="btn" style="margin-top:18px" onclick="logout()">Sign out</button>':'<p class="sub" style="margin-top:12px">Local access is enabled. Set a studio password for hosted use.</p>'}</div></div>`}
async function saveSettings(e){e.preventDefault();try{await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await refresh();render();toast('Settings saved')}catch(err){toast(err.message)}}
async function uploadStudioLogo(input){if(!input.files.length)return;let f=new FormData();f.append('logo',input.files[0]);try{await api('/api/settings/logo',{method:'POST',body:f});await refresh();render();toast('Brand mark saved. Apply it to existing photos below.')}catch(e){toast(e.message)}}
async function removeStudioLogo(){try{await api('/api/settings/logo',{method:'DELETE'});await refresh();render();toast('Mark removed. Apply the change to existing photos below.')}catch(e){toast(e.message)}}
async function applyStudioBrand(){try{toast('Applying brand to existing photos…');let r=await api('/api/settings/apply-brand',{method:'POST'});toast(r.errors.length?`${r.updated} updated; ${r.errors.length} failed.`:`Brand applied to ${r.updated} photos`)}catch(e){toast(e.message)}}
async function logout(){try{await api('/api/logout',{method:'POST'});location.assign('/')}catch(e){toast(e.message||'Unable to sign out.')}}
function brandingModal(){let g=current;modal(`<div class="modal-head"><div><div class="eyebrow">Protect & personalize</div><h2>Gallery branding</h2><p class="sub">Choose the proof watermark and a small brand mark for every image.</p></div><button class="close" onclick="closeModal()">×</button></div><form onsubmit="saveBranding(event)"><label class="field">Watermark text<input name="watermark_text" maxlength="60" value="${esc(g.watermark_text)}" placeholder="Leave empty for no text watermark"></label><div class="form-grid"><label class="field">Layout<select name="watermark_style">${options([['diagonal','Diagonal'],['center','Centered'],['tile','Repeated'],['corner','Corner']],g.watermark_style)}</select></label><label class="field">Text color<input name="watermark_color" type="color" value="${esc(g.watermark_color)}"></label><label class="field">Text opacity (%)<input type="number" name="watermark_opacity" min="0" max="100" value="${g.watermark_opacity}" required></label><label class="field">Text size (%)<input type="number" name="watermark_size" min="1" max="15" value="${g.watermark_size}" required></label></div><div class="section-title" style="margin:24px 0 0"><div><h2>Brand mark</h2><p class="sub">PNG transparency is supported. The mark appears on proofs and delivered images. Leave the gallery mark unset to use the studio mark.</p></div></div><label class="field">Upload a brand image<input id="brand-file" type="file" accept="image/png,image/jpeg,image/webp"></label>${g.watermark_logo?'<p class="sub">A brand mark is uploaded. <button type="button" class="text-link" onclick="removeBrand()">Remove mark</button></p>':''}<div class="form-grid"><label class="field">Position<select name="brand_position">${options([['bottom-right','Bottom right'],['bottom-left','Bottom left'],['top-right','Top right'],['top-left','Top left']],g.brand_position)}</select></label><label class="field">Size (%)<input type="number" name="brand_size" min="5" max="30" value="${g.brand_size}" required></label><label class="field">Opacity (%)<input type="number" name="brand_opacity" min="0" max="100" value="${g.brand_opacity}" required></label></div><p class="sub" style="margin-top:16px">Save and apply updates existing photos as well as future uploads. Processing can take a moment.</p><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save and apply</button></div></form>`)}
async function removeBrand(){try{await api('/api/galleries/'+current.id+'/logo',{method:'DELETE'});current.watermark_logo='';closeModal();brandingModal();toast('Brand mark removed; save and apply to update photos.')}catch(e){toast(e.message)}}
async function saveBranding(e){e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f));for(const k of ['watermark_opacity','watermark_size','brand_size','brand_opacity'])b[k]=Number(b[k]);try{let file=document.querySelector('#brand-file').files[0];if(file){let form=new FormData();form.append('logo',file);await api('/api/galleries/'+current.id+'/logo',{method:'POST',body:form})}await api('/api/galleries/'+current.id+'/customization',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});toast('Updating your photographs…');let r=await api('/api/galleries/'+current.id+'/regenerate',{method:'POST'});closeModal();await openGallery(current.id);toast(r.errors.length?`${r.updated} updated; ${r.errors.length} could not be processed.`:`Branding applied to ${r.updated} photos`)}catch(err){toast(err.message)}}
shareModal=function(id){let g=galleries.find(x=>x.id===id)||current,url=(config.public_url||location.origin)+'/l/'+id;modal(`<div class="modal-head"><div><div class="eyebrow">Share the story</div><h2>Share & customize</h2><p class="sub">Personalize the guest gallery, QR code, and print card.</p></div><button class="close" onclick="closeModal()">×</button></div><form onsubmit="saveShare(event,'${id}')"><label class="field">Guest gallery title<input name="share_title" maxlength="100" value="${esc(g.share_title||'')}" placeholder="${esc(g.name)}"></label><label class="field">Welcome message<input name="share_message" maxlength="240" value="${esc(g.share_message||'')}" placeholder="A collection of memories"></label><div class="form-grid"><label class="field">Accent / QR color<input name="share_color" id="qr-color" type="color" value="${esc(g.share_color||'#4f5b2a')}" oninput="updateShareQR('${id}')"></label><label class="field">QR background<input name="share_qr_background" id="qr-bg" type="color" value="${esc(g.share_qr_background||'#ffffff')}" oninput="updateShareQR('${id}')"></label></div><p id="share-qr-warning" class="studio-warning" role="status" hidden></p><div class="share-preview"><img id="share-qr" src="/api/galleries/${id}/qr?qr_color=${encodeURIComponent(g.share_color||'#4f5b2a')}&qr_background=${encodeURIComponent(g.share_qr_background||'#ffffff')}" width="130" alt="Preview of gallery QR code"><div><b>${esc(g.name)}</b><p class="sub">Scan to open the guest gallery</p></div></div><label class="field">Gallery link<input readonly value="${esc(url)}" onclick="this.select()"></label><div class="form-grid"><label class="field">Print format<select id="print-layout">${options([['card','Table tent'],['a4','A4 poster'],['sticker','Sticker'],['story','Story']],'card')}</select></label><label class="field">Print theme<select id="print-theme">${options([['minimalist','Minimalist'],['luxury','Luxury'],['botanical','Botanical'],['monolith','Monolith']],'minimalist')}</select></label></div><div class="modal-actions wrap"><button type="button" class="btn" onclick="openDesignerFromShare('${id}')">Design card</button><button type="button" class="btn" onclick="openPrint('${id}')">Quick print</button><button type="button" class="btn" onclick="downloadQR('${id}','svg')">SVG</button><button type="button" class="btn" onclick="downloadQR('${id}','png')">PNG</button><button type="button" class="btn" onclick="copyShare('${url}')">Copy link</button><button class="btn primary">Save sharing</button></div></form>`);updateShareQR(id)}
openPrint=function(id){let form=document.querySelector('#qr-color').form;let q=new URLSearchParams({layout:document.querySelector('#print-layout').value,theme:document.querySelector('#print-theme').value,qr_color:document.querySelector('#qr-color').value,qr_background:document.querySelector('#qr-bg').value,title:form.elements.share_title.value,message:form.elements.share_message.value});window.open('/api/galleries/'+id+'/print?'+q,'_blank')};
function updateShareQR(id){const fg=document.querySelector('#qr-color').value,bg=document.querySelector('#qr-bg').value;document.querySelector('#share-qr').src='/api/galleries/'+id+'/qr?qr_color='+encodeURIComponent(fg)+'&qr_background='+encodeURIComponent(bg);const lum=hex=>{let p=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*p[0]+.7152*p[1]+.0722*p[2]},a=lum(fg),b=lum(bg),warning=document.querySelector('#share-qr-warning');if(warning){let low=(Math.max(a,b)+.05)/(Math.min(a,b)+.05)<4.5,inverted=a>b;warning.hidden=!low&&!inverted;warning.textContent=low?'QR colors have low contrast. Test the code before sharing or printing.':'Light QR marks on a dark background may not scan on every device.'}} 
function downloadQR(id,format){let a=document.createElement('a');a.href='/api/galleries/'+id+'/qr?format='+format+'&qr_color='+encodeURIComponent(document.querySelector('#qr-color').value)+'&qr_background='+encodeURIComponent(document.querySelector('#qr-bg').value);a.download='pictide-qr.'+format;document.body.append(a);a.click();a.remove()}
async function copyShare(url){try{await navigator.clipboard.writeText(url);toast('Link copied')}catch{toast('Select and copy the gallery link above.')}}
async function saveShare(e,id){e.preventDefault();try{let b=Object.fromEntries(new FormData(e.target));await api('/api/galleries/'+id+'/customization',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});closeModal();await refresh();if(current?.id===id)current=await api('/api/galleries/'+id);render();toast('Sharing preferences saved')}catch(err){toast(err.message)}}
renderGuest=async function(){let id=new URLSearchParams(location.search).get('gallery');try{current=await api('/api/galleries/'+id)}catch{app.innerHTML='<div class="guest-hero"><h1>Gallery not found</h1><p>Please check your link and try again.</p></div>';return}let g=current;if(g.status!=='Published'&&!new URLSearchParams(location.search).has('preview')){app.innerHTML='<div class="guest-hero"><h1>This gallery is not available yet.</h1><p>Please check back with your photographer.</p></div>';return}let saved=JSON.parse(localStorage.getItem('lumen-orders-'+id)||'[]'),old=JSON.parse(localStorage.getItem('lumen-order-'+id)||'null');if(old&&!saved.some(x=>x.order===old.order))saved.push(old);favorites=new Set(JSON.parse(localStorage.getItem('lumen-favorites-'+id)||'[]'));unlocked=new Set();photoTokens={};for(const item of saved)try{let result=await api('/api/checkout/'+item.order+'/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:item.token})});if(result.status==='Paid')for(const p of result.photos){unlocked.add(p);photoTokens[p]=item.token} }catch{}g.photos=g.photos.filter(p=>(!g.archived&&!p.archived)||unlocked.has(p.id));app.innerHTML=`<div class="guest" style="--guest-accent:${esc(g.share_color)}">${new URLSearchParams(location.search).has('preview')?'<div class="preview-banner">Guest preview · Checkout and uploads are disabled <a href="/">Return to workspace</a></div>':''}<header class="guest-nav"><div class="brand"><span class="brand-mark">✳</span> ${esc(g.studio_name)}</div><button class="btn theme-toggle" onclick="toggleTheme()">${theme==='dark'?'☀ Light':'☾ Dark'}</button></header><div class="guest-hero ${g.cover_photo?'has-cover':''}" ${g.cover_photo?`style="background-image:linear-gradient(0deg,rgba(22,29,22,.78),rgba(22,29,22,.28)),url('/media/${g.cover_photo}')"`:''}><div class="eyebrow">The moments that matter</div><h1>${esc(g.share_title||g.name)}</h1><p>${esc(g.share_message||g.location||'A collection of memories')} &nbsp; · &nbsp; ${date(g.event_date)}</p></div><div class="section-title"><div><h2>Your photographs</h2><p class="sub">Find your favorites and select the moments you love.</p></div><span class="sub">${g.photos.length} photos</span></div><div class="guest-actions">${g.photos.some(p=>photoPrice(p)===0)?`<a class="btn" href="/api/galleries/${g.id}/free-download">${icon('download')} Download free photos</a>`:''}${g.contact_email?`<a class="btn" href="mailto:${encodeURIComponent(g.contact_email)}">${icon('mail')} Contact photographer</a>`:''}${g.allow_guest_upload?`<button class="btn" onclick="document.querySelector('#guest-upload').click()">${icon('upload')} Add photos</button><input id="guest-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden onchange="submitGuestPhotos(this)">`: ``}<button class="btn" onclick="showMyUploads()">My uploads</button></div><div class="toolbar filters"><input class="search" aria-label="Search photographs" placeholder="Search photographs..." value="${esc(guestQuery)}" oninput="guestQuery=this.value;updateGuestGrid()"><select aria-label="Filter photographs" onchange="guestFilter=this.value;updateGuestGrid()">${options([['all','All photos'],['favorites','Favorites'],['free','Free photos'],['locked','Paid photos'],['selected','Selected'],['purchased','Purchased']],guestFilter)}</select><select aria-label="Sort photographs" onchange="guestSort=this.value;updateGuestGrid()">${options([['newest','Newest first'],['oldest','Oldest first'],['name','Name A–Z'],['price-low','Price: low to high'],['price-high','Price: high to low']],guestSort)}</select><button class="btn" onclick="selectAllVisible()">Select all shown</button><button class="btn" onclick="toggleGuestLayout()" id="layout-toggle">List view</button></div><div class="detail-grid" id="guest-photos"></div><div id="guest-photo-more"></div><div class="selection-bar"><span id="selection-summary"></span><button class="btn" onclick="showSelectionPanel()">${icon('shopping-bag')} View selection</button></div><aside id="selection-panel" class="selection-panel" aria-label="Selected photographs" hidden></aside></div>`;updateGuestGrid();icons()}
function guestGlyph(name){const paths={plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 18v2h14v-2"/>',heart:'<path d="M20.8 4.9a5.3 5.3 0 0 0-7.5 0L12 6.2l-1.3-1.3a5.3 5.3 0 0 0-7.5 7.5L12 21l8.8-8.6a5.3 5.3 0 0 0 0-7.5Z"/>'};return `<svg class="guest-control-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="#303b25" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${paths[name]}</svg>`}
function updateGuestGrid(){let sig=JSON.stringify([current.id,guestQuery,guestFilter,guestSort]);if(sig!==guestPhotoSignature){guestPhotoSignature=sig;guestPhotoLimit=60}let list=sortPhotos(current.photos.filter(p=>p.name.toLowerCase().includes(guestQuery.toLowerCase())&&(guestFilter==='all'||guestFilter==='favorites'&&favorites.has(p.id)||guestFilter==='free'&&photoPrice(p)===0||guestFilter==='locked'&&photoPrice(p)>0&&!unlocked.has(p.id)||guestFilter==='selected'&&selected.has(p.id)||guestFilter==='purchased'&&unlocked.has(p.id))),guestSort);document.querySelector('#guest-photos').innerHTML=list.slice(0,guestPhotoLimit).map(p=>`<div class="photo ${selected.has(p.id)?'selected':''}"><img loading="lazy" decoding="async" src="${unlocked.has(p.id)||photoPrice(p)===0?'/api/photos/'+p.id+'/clean?token='+(photoTokens[p.id]||'')+'&size=thumb':'/media/'+p.id+'?size=thumb'}" alt="${esc(p.name)}" onclick="lightbox(${current.photos.indexOf(p)})"><button class="favorite ${favorites.has(p.id)?'is-favorite':''}" style="left:10px;right:auto" aria-pressed="${favorites.has(p.id)}" aria-label="${favorites.has(p.id)?'Remove favorite':'Add favorite'}" onclick="toggleFavorite('${p.id}')">${guestGlyph('heart')}</button><button aria-pressed="${selected.has(p.id)}" aria-label="${unlocked.has(p.id)?'Download photo':selected.has(p.id)?'Remove from cart':'Add to cart'}" onclick="${unlocked.has(p.id)?`downloadPhoto('${p.id}')`:`selectPhoto('${p.id}')`}">${guestGlyph(unlocked.has(p.id)?'download':selected.has(p.id)?'check':'plus')}</button><span class="price-tag">${unlocked.has(p.id)?'Purchased':photoPrice(p)===0?'Free':money(photoPrice(p))}</span><span class="photo-name">${esc(p.name)}</span></div>`).join('')||'<div class="empty-state">No photos match these filters.</div>';document.querySelector('#guest-photo-more').innerHTML=list.length>guestPhotoLimit?`<div class="photo-load-more"><span>Showing ${Math.min(guestPhotoLimit,list.length)} of ${list.length} photographs</span><button class="btn" onclick="loadMoreGuestPhotos()">Load more</button></div>`:'';document.querySelector('#selection-summary').innerHTML=`<b>${selected.size} selected</b> &nbsp; · &nbsp; ${money(selectionTotal())}`;updateSelectionPanel()}
toggleFavorite=function(id){favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('lumen-favorites-'+current.id,JSON.stringify([...favorites]));updateGuestGrid()}
selectPhoto=function(id){let adding=!selected.has(id);adding?selected.add(id):selected.delete(id);updateGuestGrid();if(adding)showSelectionPanel()}
function updateSelectionPanel(){let panel=document.querySelector('#selection-panel');if(!panel)return;if(!selected.size){panel.hidden=true;panel.innerHTML='';return}let photos=[...selected].map(id=>current.photos.find(p=>p.id===id)).filter(Boolean),free=photos.filter(p=>photoPrice(p)===0).length,stack=photos.slice(-4);panel.innerHTML=`<div class="selection-panel-head"><div>Selected <span class="selection-count">${photos.length}</span></div><button class="selection-close" aria-label="Close selection panel" onclick="hideSelectionPanel()">×</button></div><div class="selection-stack" aria-label="Preview of selected photos">${stack.map((p,i)=>`<div class="selection-stack-card" style="--stack-index:${i};--stack-rotation:${[-3,2,-2,3][i]}deg"><img src="/media/${p.id}" alt="${esc(p.name)}"><span>${photoPrice(p)===0?'Free':money(photoPrice(p))}</span></div>`).join('')}</div><div class="selection-panel-total"><span>${photos.length} selected (${free} free, ${photos.length-free} paid)</span><strong>${money(selectionTotal())}</strong></div><button class="selection-cart-button" onclick="hideSelectionPanel();openCart()">${icon('shopping-cart')} View selected cart</button>`;icons()}
function showSelectionPanel(){if(!selected.size)return toast('Select at least one photo first.');let panel=document.querySelector('#selection-panel');if(!panel)return;updateSelectionPanel();panel.hidden=false;panel.classList.remove('selection-panel-enter');void panel.offsetWidth;panel.classList.add('selection-panel-enter')}
function hideSelectionPanel(){let panel=document.querySelector('#selection-panel');if(panel)panel.hidden=true}
function openCart(){if(!selected.size)return toast('Select at least one photo first.');let photos=current.photos.filter(p=>selected.has(p.id)),free=photos.filter(p=>photoPrice(p)===0).length;modal(`<div class="modal-head"><div><div class="eyebrow">Your selection</div><h2>Your cart <span class="cart-count">${photos.length}</span></h2><p class="sub">${free} free · ${photos.length-free} paid</p></div><button class="close" aria-label="Close cart" onclick="closeModal()">×</button></div><div class="cart-items">${photos.map(p=>`<div class="cart-item"><img src="/media/${p.id}" alt=""><div><b>${esc(p.name)}</b><small>${photoPrice(p)===0?'Free':money(photoPrice(p))}</small></div><button class="text-link" aria-label="Remove ${esc(p.name)}" onclick="selectPhoto('${p.id}');closeModal();if(selected.size)openCart()">Remove</button></div>`).join('')}</div><div class="cart-total"><span>Total</span><strong>${money(selectionTotal())}</strong></div><div class="modal-actions"><button class="btn primary" onclick="closeModal();checkoutModal()">${selectionTotal()?'Continue to checkout':'Get free photos'} ${icon('arrow-right')}</button></div>`);icons()}
checkoutModal=function(){if(!selected.size)return toast('Select at least one photo first.');if(new URLSearchParams(location.search).has('preview'))return toast('Checkout is disabled in guest preview.');let total=selectionTotal();modal(`<div class="modal-head"><div><div class="eyebrow">Your selection</div><h2>Keep these moments.</h2><p class="sub">${selected.size} photos · ${money(total)}</p></div><button class="close" onclick="closeModal()">×</button></div><div class="checkout-items">${current.photos.filter(p=>selected.has(p.id)).map(p=>`<div><span>${esc(p.name)}</span><b>${photoPrice(p)===0?'Free':money(photoPrice(p))}</b></div>`).join('')}</div><p class="sub" style="margin-top:20px">${!total?'Your selected photos are free.':config.payments==='paystack'?'You will be taken to Paystack to complete your payment.':'Payments are currently unavailable. Please contact your photographer.'}</p><form onsubmit="checkout(event)"><label class="field">Email address<input type="email" name="email" required placeholder="you@example.com"></label><div class="modal-actions"><button type="button" class="btn" onclick="closeModal();openCart()">Back to cart</button><button class="btn primary" ${total&&config.payments==='unavailable'?'disabled':''}>${total?'Continue to payment':'Get photos'}</button></div></form>`)}

let guestLayout='grid';
async function toggleGuestUploads(){try{await api('/api/galleries/'+current.id+'/customization',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({allow_guest_upload:current.allow_guest_upload?0:1})});await refresh();await openGallery(current.id);toast(current.allow_guest_upload?'Guest uploads enabled':'Guest uploads disabled')}catch(e){toast(e.message)}}
async function reviewUploads(){try{let rows=await api('/api/galleries/'+current.id+'/guest-uploads');modal(`<div class="modal-head"><div><div class="eyebrow">Guest contributions</div><h2>Review submissions</h2><p class="sub">Only approved photos appear in the gallery, as free photos.</p></div><button class="close" onclick="closeModal()">×</button></div><div class="review-list">${rows.map(p=>`<div class="review-row">${p.status==='pending'?`<img src="/api/guest-uploads/${p.id}/preview" alt="${esc(p.name)}">`:''}<div><b>${esc(p.name)}</b><p class="sub">${esc(p.status)} · ${date(p.created)}</p></div>${p.status==='pending'?`<div class="review-actions"><button class="btn" onclick="reviewSubmission('${p.id}','reject')">Reject</button><button class="btn primary" onclick="reviewSubmission('${p.id}','approve')">Approve</button></div>`:''}</div>`).join('')||'<p class="sub">No submissions yet.</p>'}</div>`)}catch(e){toast(e.message)}}
async function reviewSubmission(id,action){try{await api('/api/guest-uploads/'+id+'/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});closeModal();await refresh();await openGallery(current.id);await reviewUploads();toast(action==='approve'?'Photo approved and added as free':'Submission rejected')}catch(e){toast(e.message)}}
async function submitGuestPhotos(input){if(new URLSearchParams(location.search).has('preview')){input.value='';return toast('Uploads are disabled in guest preview.')}if(!input.files.length)return;if(input.files.length>5){input.value='';return toast('Upload up to five images at a time.')}let f=new FormData();for(const file of input.files)f.append('photos',file);try{toast('Uploading photos for review…');let r=await api('/api/galleries/'+current.id+'/guest-uploads',{method:'POST',body:f});if(r.added.length){let key='lumen-uploads-'+current.id,stored=JSON.parse(localStorage.getItem(key)||'[]');stored.push(r.token);localStorage.setItem(key,JSON.stringify(stored));}input.value='';toast(`${r.added.length} submitted for review${r.errors.length?' · '+r.errors.join(', '):''}`)}catch(e){input.value='';toast(e.message)}}
async function showMyUploads(){try{let tokens=JSON.parse(localStorage.getItem('lumen-uploads-'+current.id)||'[]');let rows=await api('/api/guest-uploads/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tokens})});modal(`<div class="modal-head"><div><div class="eyebrow">Your contributions</div><h2>My uploads</h2><p class="sub">The photographer reviews each submission before it appears in the gallery.</p></div><button class="close" onclick="closeModal()">×</button></div><div class="review-list">${rows.map(p=>`<div class="review-row"><div><b>${esc(p.name)}</b><p class="sub">${esc(p.status)} · ${date(p.created)}</p></div></div>`).join('')||'<p class="sub">No uploads from this browser yet.</p>'}</div>`)}catch(e){toast(e.message)}}
function loadMoreGuestPhotos(){guestPhotoLimit+=60;updateGuestGrid()}
function visibleGuestPhotos(){return sortPhotos(current.photos.filter(p=>p.name.toLowerCase().includes(guestQuery.toLowerCase())&&(guestFilter==='all'||guestFilter==='favorites'&&favorites.has(p.id)||guestFilter==='free'&&photoPrice(p)===0||guestFilter==='locked'&&photoPrice(p)>0&&!unlocked.has(p.id)||guestFilter==='selected'&&selected.has(p.id)||guestFilter==='purchased'&&unlocked.has(p.id))),guestSort).slice(0,guestPhotoLimit)}
function selectAllVisible(){let eligible=visibleGuestPhotos().filter(p=>!unlocked.has(p.id));if(!eligible.length)return toast('No photos in view to select.');let all=eligible.every(p=>selected.has(p.id));for(const p of eligible)all?selected.delete(p.id):selected.add(p.id);updateGuestGrid();if(!all)showSelectionPanel()}
function toggleGuestLayout(){guestLayout=guestLayout==='grid'?'list':'grid';let el=document.querySelector('#guest-photos');el.classList.toggle('photo-list',guestLayout==='list');document.querySelector('#layout-toggle').textContent=guestLayout==='grid'?'List view':'Grid view'}
downloadPhoto=async function(id){let p=current.photos.find(x=>x.id===id);if(p&&photoPrice(p)===0&&!unlocked.has(id)){location.href='/api/photos/'+id+'/free';return}try{let r=await api('/api/photos/'+id+'/download-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:photoTokens[id]})});location.href=r.url}catch(e){toast(e.message)}}
lightbox=function(index){lightboxIndex=index;let p=current.photos[index],free=photoPrice(p)===0,available=free||unlocked.has(p.id);modal(`<div class="modal-head"><div><div class="eyebrow">Photo ${index+1} of ${current.photos.length} · ${free?'Free':money(photoPrice(p))}</div><h2>${esc(p.name)}</h2></div><button class="close" onclick="closeModal()">×</button></div><img style="width:100%;max-height:60vh;object-fit:contain;margin-top:20px" src="${available?'/api/photos/'+p.id+'/clean?token='+(photoTokens[p.id]||''):'/media/'+p.id}" alt="${esc(p.name)}"><div class="modal-actions"><button class="btn" onclick="closeModal();lightbox(${(index-1+current.photos.length)%current.photos.length})">← Previous</button><button class="btn" onclick="closeModal();lightbox(${(index+1)%current.photos.length})">Next →</button><button class="btn primary" onclick="closeModal();${unlocked.has(p.id)?`downloadPhoto('${p.id}')`:`selectPhoto('${p.id}')`}">${unlocked.has(p.id)?'Download':selected.has(p.id)?'Remove from cart':'Add to cart'}</button></div>`)}
function passwordModal(){modal(`<div class="modal-head"><div><div class="eyebrow">Account protection</div><h2>${sessionInfo.passwordRequired?'Change':'Set'} studio password</h2><p class="sub">Use at least 12 characters. Existing sessions will be signed out.</p></div><button class="close" onclick="closeModal()">×</button></div><form onsubmit="changePassword(event)">${sessionInfo.passwordRequired?'<label class="field">Current password<input name="current" type="password" autocomplete="current-password" required></label>':''}<label class="field">New password<input name="password" type="password" minlength="12" maxlength="200" autocomplete="new-password" required></label><label class="field">Confirm password<input name="confirm" type="password" minlength="12" maxlength="200" autocomplete="new-password" required></label><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save password</button></div></form>`)}
async function changePassword(e){e.preventDefault();let b=Object.fromEntries(new FormData(e.target));if(b.password!==b.confirm)return toast('Passwords do not match.');try{await api('/api/security/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current:b.current||'',password:b.password})});closeModal();toast('Password updated. Please sign in.');await boot()}catch(err){toast(err.message)}}
let cardState=null,cardGallery=null,cardSelected='title',cardQR=null,cardBackground=null,cardBounds={},cardDrag=null,qrRequest=0;
function defaultCard(g){return {format:'card',background:'#f4f0e6',qrColor:g.share_color||'#4f5b2a',qrBackground:g.share_qr_background||'#ffffff',backgroundImage:'',elements:[{id:'eyebrow',text:'A COLLECTION OF MOMENTS',x:.5,y:.15,size:20,color:'#4f5b2a',font:'sans-serif',align:'center',bold:true,visible:true},{id:'title',text:g.share_title||g.name,x:.5,y:.26,size:52,color:'#252b23',font:'Georgia',align:'center',bold:false,visible:true},{id:'subtitle',text:g.share_message||'Scan to view your photographs',x:.5,y:.43,size:21,color:'#555e4d',font:'sans-serif',align:'center',bold:false,visible:true},{id:'qr',text:'',x:.5,y:.63,size:200,color:'#4f5b2a',font:'sans-serif',align:'center',bold:false,visible:true},{id:'url',text:(config.public_url||location.origin).replace(/^https?:\/\//,'')+'/l/'+g.id,x:.5,y:.88,size:16,color:'#555e4d',font:'sans-serif',align:'center',bold:false,visible:true}]}}
async function openCardDesigner(id){try{let g=await api('/api/galleries/'+id);cardGallery=g;cardQR=null;cardBackground=null;try{cardState=g.card_design?JSON.parse(g.card_design):defaultCard(g);if(!Array.isArray(cardState.elements)||!cardState.elements.length)throw Error()}catch{cardState=defaultCard(g)}cardSelected=cardState.elements.find(x=>x.id==='title')?.id||cardState.elements[0].id;modal(`<div class="modal-head"><div><div class="eyebrow">Print studio</div><h2>Make your card your own.</h2><p class="sub">Drag elements on the preview or use the positioning buttons.</p></div><button class="close" onclick="closeModal()">×</button></div><div class="designer"><div><div class="designer-preview"><canvas id="card-canvas" width="900" height="1200" aria-label="Card preview. Select an element and use the move buttons to reposition it."></canvas></div><div class="modal-actions wrap"><button class="btn" onclick="exportCard()">Download PNG</button><button class="btn" onclick="printCard()">Print / PDF</button><button class="btn primary" onclick="saveCard()">Save design</button></div></div><div class="designer-controls"><label class="field">Format<select id="card-format" onchange="cardState.format=this.value;drawCard()">${options([['card','Table tent'],['a4','A4 poster'],['sticker','Sticker'],['story','Story']],cardState.format||'card')}</select></label><div class="form-grid"><label class="field">Background<input type="color" value="${esc(cardState.background||'#f4f0e6')}" oninput="cardState.background=this.value;drawCard()"></label><label class="field">QR color<input type="color" value="${esc(cardState.qrColor||'#4f5b2a')}" oninput="cardState.qrColor=this.value;loadCardQR()"></label></div><label class="field">Style preset<select onchange="applyCardPreset(this.value)"><option value="">Choose a style…</option><option value="minimal">Minimal</option><option value="olive">Olive garden</option><option value="midnight">Midnight</option><option value="gold">Warm gold</option></select></label><div class="form-grid"><label class="field">Photo shading (%)<input type="range" min="0" max="80" value="${cardState.overlay||0}" oninput="cardState.overlay=Number(this.value);drawCard()"></label><label class="field">Border color<input type="color" value="${esc(cardState.borderColor||'#4f5b2a')}" oninput="cardState.borderColor=this.value;drawCard()"></label><label class="field">Border width<input type="range" min="0" max="24" value="${cardState.borderWidth||0}" oninput="cardState.borderWidth=Number(this.value);drawCard()"></label></div><label class="field">Background image<input type="file" accept="image/png,image/jpeg,image/webp" onchange="setCardBackground(this)"></label><button class="text-link" onclick="cardState.backgroundImage='';cardBackground=null;drawCard()">Remove background image</button>${g.cover_photo?'<button class="text-link" onclick="useCardCover()">Use gallery cover</button>':''}<div class="card-elements" id="card-elements"></div><div id="card-properties"></div><div class="modal-actions wrap"><button class="btn" onclick="addCardText()">+ Add text</button><button class="btn" onclick="resetCard()">Reset layout</button></div></div></div>`);document.querySelector('#modal .modal').classList.add('designer-modal');let c=document.querySelector('#card-canvas');c.addEventListener('pointerdown',cardPointerDown);c.addEventListener('pointermove',cardPointerMove);c.addEventListener('pointerup',()=>cardDrag=null);if(cardState.backgroundImage)loadCardBackground(cardState.backgroundImage);loadCardQR();renderCardControls();drawCard()}catch(e){toast(e.message)}}
function renderCardControls(){let element=cardState.elements.find(x=>x.id===cardSelected);document.querySelector('#card-elements').innerHTML=cardState.elements.map(e=>`<button class="btn ${e.id===cardSelected?'primary':''}" onclick="cardSelected='${esc(e.id)}';renderCardControls();drawCard()">${esc(e.id==='qr'?'QR code':e.id)}</button>`).join('');if(!element)return;document.querySelector('#card-properties').innerHTML=`<div class="section-title" style="margin:24px 0 0"><div><div class="eyebrow">Selected element</div><h2>${esc(element.id==='qr'?'QR code':element.id)}</h2></div><label><input type="checkbox" ${element.visible?'checked':''} onchange="setCardProperty('visible',this.checked)"> Visible</label></div>${element.id!=='qr'?`<label class="field">Text<input maxlength="150" value="${esc(element.text)}" oninput="setCardProperty('text',this.value)"></label><div class="form-grid"><label class="field">Font<select onchange="setCardProperty('font',this.value)">${options([['Georgia','Serif'],['sans-serif','Sans serif'],['monospace','Monospace']],element.font)}</select></label><label class="field">Text color<input type="color" value="${esc(element.color)}" oninput="setCardProperty('color',this.value)"></label><label class="field">Alignment<select onchange="setCardProperty('align',this.value)">${options([['left','Left'],['center','Center'],['right','Right']],element.align)}</select></label><label class="field">Weight<select onchange="setCardProperty('bold',this.value==='bold')">${options([['normal','Regular'],['bold','Bold']],element.bold?'bold':'normal')}</select></label></div>`:''}<div class="form-grid"><label class="field">Opacity (%)<input type="range" min="0" max="100" value="${element.opacity??100}" oninput="setCardProperty('opacity',Number(this.value))"></label><label class="field">Rotation (degrees)<input type="number" min="-180" max="180" value="${element.rotation||0}" oninput="setCardProperty('rotation',Math.max(-180,Math.min(180,Number(this.value))))"></label></div>${element.id!=='qr'?`<label><input type="checkbox" ${element.italic?'checked':''} onchange="setCardProperty('italic',this.checked)"> Italic text</label>`:''}<div class="details-bar" style="margin-top:12px"><button class="btn" onclick="reorderCard(-1)">Send backward</button><button class="btn" onclick="reorderCard(1)">Bring forward</button><button class="btn" onclick="duplicateCardText()">Duplicate text</button></div><label class="field">Size<input type="range" min="${element.id==='qr'?80:10}" max="${element.id==='qr'?360:100}" value="${element.size}" oninput="setCardProperty('size',Number(this.value))"></label><div class="field">Move element<div class="details-bar"><button class="btn" onclick="moveCard(-.02,0)">←</button><button class="btn" onclick="moveCard(0,-.02)">↑</button><button class="btn" onclick="moveCard(0,.02)">↓</button><button class="btn" onclick="moveCard(.02,0)">→</button><button class="btn" onclick="centerCard()">Center</button>${element.id.startsWith('custom')?'<button class="btn" onclick="removeCardText()">Remove</button>':''}</div></div>`}
function setCardProperty(key,value){let e=cardState.elements.find(x=>x.id===cardSelected);e[key]=value;drawCard()}
function moveCard(x,y){let e=cardState.elements.find(x=>x.id===cardSelected);e.x=Math.max(.03,Math.min(.97,e.x+x));e.y=Math.max(.03,Math.min(.97,e.y+y));drawCard()}
function centerCard(){let e=cardState.elements.find(x=>x.id===cardSelected);e.x=.5;drawCard()}
function addCardText(){let id='custom'+Date.now();cardState.elements.push({id,text:'Add your message',x:.5,y:.5,size:24,color:'#252b23',font:'sans-serif',align:'center',bold:false,visible:true});cardSelected=id;renderCardControls();drawCard()}
function removeCardText(){cardState.elements=cardState.elements.filter(x=>x.id!==cardSelected);cardSelected=cardState.elements[0].id;renderCardControls();drawCard()}
function resetCard(){cardState=defaultCard(cardGallery);cardSelected='title';cardBackground=null;document.querySelector('#card-format').value='card';loadCardQR();renderCardControls();drawCard()}
function loadCardQR(){let sequence=++qrRequest;cardQR=null;let img=new Image();img.onload=()=>{if(sequence!==qrRequest)return;cardQR=img;drawCard()};img.src='/api/galleries/'+cardGallery.id+'/qr?format=png&qr_color='+encodeURIComponent(cardState.qrColor)}
function loadCardBackground(src){let image=new Image();image.onload=()=>{cardBackground=image;drawCard()};image.src=src}
function useCardCover(){let image=new Image();image.onload=()=>{let c=document.createElement('canvas'),scale=Math.min(1,1000/image.width,1000/image.height);c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));c.getContext('2d').drawImage(image,0,0,c.width,c.height);cardState.backgroundImage=c.toDataURL('image/jpeg',.72);loadCardBackground(cardState.backgroundImage)};image.src='/media/'+cardGallery.cover_photo}
function setCardBackground(input){let file=input.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)return toast('Choose a PNG, JPEG or WebP under 10 MB.');let reader=new FileReader();reader.onload=()=>{let image=new Image();image.onload=()=>{let c=document.createElement('canvas'),scale=Math.min(1,1000/image.width,1000/image.height);c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));c.getContext('2d').drawImage(image,0,0,c.width,c.height);cardState.backgroundImage=c.toDataURL('image/jpeg',.72);loadCardBackground(cardState.backgroundImage)};image.src=reader.result};reader.readAsDataURL(file)}
function applyCardPreset(name){let presets={minimal:['#ffffff','#242b22','#4f5b2a'],olive:['#e9eedc','#334225','#4f5b2a'],midnight:['#202722','#f8f5e9','#4f5b2a'],gold:['#f8edd6','#4a3b27','#b8892d']};if(!presets[name])return;let [bg,ink,qr]=presets[name];cardState.background=bg;cardState.qrColor=qr;cardState.borderColor=ink;for(const e of cardState.elements)if(e.id!=='qr')e.color=ink;document.querySelectorAll('.designer-controls input[type=color]')[0].value=bg;document.querySelectorAll('.designer-controls input[type=color]')[1].value=qr;loadCardQR();renderCardControls();drawCard()}
function reorderCard(direction){let i=cardState.elements.findIndex(e=>e.id===cardSelected),j=Math.max(0,Math.min(cardState.elements.length-1,i+direction));if(i!==j)[cardState.elements[i],cardState.elements[j]]=[cardState.elements[j],cardState.elements[i]];renderCardControls();drawCard()}
function duplicateCardText(){let e=cardState.elements.find(x=>x.id===cardSelected);if(e.id==='qr')return toast('Choose a text element to duplicate.');if(cardState.elements.length>=20)return toast('The card can contain up to 20 elements.');let copy={...e,id:'custom'+Date.now(),x:Math.min(.95,e.x+.03),y:Math.min(.95,e.y+.05)};cardState.elements.push(copy);cardSelected=copy.id;renderCardControls();drawCard()}
function drawCard(){let c=document.querySelector('#card-canvas');if(!c||!cardState)return;let sizes={card:[900,1200],a4:[900,1273],sticker:[900,900],story:[900,1600]},dims=sizes[cardState.format]||sizes.card;if(c.width!==dims[0]||c.height!==dims[1]){c.width=dims[0];c.height=dims[1]}let ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle=cardState.background||'#f4f0e6';ctx.fillRect(0,0,w,h);if(cardBackground){let scale=Math.max(w/cardBackground.width,h/cardBackground.height),iw=cardBackground.width*scale,ih=cardBackground.height*scale;ctx.drawImage(cardBackground,(w-iw)/2,(h-ih)/2,iw,ih);ctx.fillStyle='rgba(0,0,0,'+((cardState.overlay||0)/100)+')';ctx.fillRect(0,0,w,h)}if(cardState.borderWidth){ctx.strokeStyle=cardState.borderColor||'#4f5b2a';ctx.lineWidth=cardState.borderWidth*2;ctx.strokeRect(30,30,w-60,h-60)}cardBounds={};for(const e of cardState.elements){if(!e.visible)continue;let x=e.x*w,y=e.y*h;ctx.save();ctx.globalAlpha=(e.opacity??100)/100;ctx.translate(x,y);ctx.rotate((e.rotation||0)*Math.PI/180);if(e.id==='qr'){let size=e.size*2;if(cardQR){ctx.fillStyle='#fff';ctx.fillRect(-size/2-10,-size/2-10,size+20,size+20);ctx.drawImage(cardQR,-size/2,-size/2,size,size)}cardBounds[e.id]=[x-size/2,y-size/2,size,size];ctx.restore();continue}let size=e.size*2;ctx.font=`${e.italic?'italic ':''}${e.bold?'bold ':''}${size}px ${e.font}`;ctx.textAlign=e.align;ctx.textBaseline='middle';ctx.fillStyle=e.color;let max=w*.82,lines=[],line='';for(const word of e.text.split(/\s+/)){let candidate=line?line+' '+word:word;if(line&&ctx.measureText(candidate).width>max){lines.push(line);line=word}else line=candidate}if(line||!lines.length)lines.push(line);let lineHeight=size*1.15,top=-(lines.length-1)*lineHeight/2;lines.forEach((line,i)=>ctx.fillText(line,0,top+i*lineHeight,max));let width=Math.min(max,Math.max(...lines.map(line=>ctx.measureText(line).width))),left=e.align==='left'?x:e.align==='right'?x-width:x-width/2;cardBounds[e.id]=[left,y+top-size/2,width,size+(lines.length-1)*lineHeight];ctx.restore()}}
function cardPointerDown(event){let c=event.currentTarget,r=c.getBoundingClientRect(),x=(event.clientX-r.left)*c.width/r.width,y=(event.clientY-r.top)*c.height/r.height;let hit=[...cardState.elements].reverse().find(e=>{let b=cardBounds[e.id];return b&&x>=b[0]-12&&x<=b[0]+b[2]+12&&y>=b[1]-12&&y<=b[1]+b[3]+12});if(hit){cardSelected=hit.id;cardDrag=hit.id;c.setPointerCapture(event.pointerId);renderCardControls()}}
function cardPointerMove(event){if(!cardDrag)return;let c=event.currentTarget,r=c.getBoundingClientRect(),e=cardState.elements.find(x=>x.id===cardDrag);e.x=Math.max(.03,Math.min(.97,(event.clientX-r.left)/r.width));e.y=Math.max(.03,Math.min(.97,(event.clientY-r.top)/r.height));drawCard()}
async function saveCard(){try{await api('/api/galleries/'+cardGallery.id+'/card-design',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(cardState)});toast('Card design saved')}catch(e){toast(e.message)}}
function exportCard(){if(cardState.elements.some(e=>e.id==='qr'&&e.visible)&&!cardQR)return toast('The QR code is still loading.');let a=document.createElement('a');a.download='pictide-card.png';a.href=document.querySelector('#card-canvas').toDataURL('image/png');a.click()}
function printCard(){if(cardState.elements.some(e=>e.id==='qr'&&e.visible)&&!cardQR)return toast('The QR code is still loading.');let png=document.querySelector('#card-canvas').toDataURL('image/png'),w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print this card.');let format=cardState.format,printSize=({card:'4in 6in',a4:'A4',sticker:'80mm 80mm',story:'108mm 192mm'})[format]||'4in 6in';w.document.write(`<!doctype html><title>Print gallery card</title><style>@page{size:${printSize};margin:0}body{margin:0;text-align:center}img{display:block;width:100%;height:100vh;object-fit:contain}@media print{button{display:none}}</style><img alt="Gallery card" src="${png}"><button onclick="print()">Print or save as PDF</button>`);w.document.close()}

async function loadContributionPreview(){let host=document.querySelector('#contribution-preview');if(!host||!current)return;try{let rows=(await api('/api/galleries/'+current.id+'/guest-uploads')).filter(p=>p.status==='pending');if(!host.isConnected)return;host.innerHTML=rows.length?`<span>${rows.length} awaiting review</span><span class="contribution-thumbs">${rows.slice(0,5).map(p=>`<img src="/api/guest-uploads/${p.id}/preview" alt="${esc(p.name)}">`).join('')}</span>`:'<span>No submissions awaiting review.</span>'}catch{if(host.isConnected)host.textContent='Could not load submissions.'}}
const originalOpenGallery=openGallery;openGallery=async function(id){ownerPhotoLimit=60;ownerPhotoSignature=JSON.stringify([id,photoQuery,photoFilter,photoSort]);await originalOpenGallery(id);loadContributionPreview()};
async function syncOrder(id){try{let r=await api('/api/orders/'+id+'/sync',{method:'POST'});toast('Order status: '+r.status);await navigate('orders')}catch(e){toast(e.message)}}
